import{_ as a,o as l,c as o,a2 as t}from"./chunks/framework.DA0HUBZR.js";const u=JSON.parse('{"title":"内容更新规则","description":"","frontmatter":{},"headers":[],"relativePath":"kb/rules.md","filePath":"kb/rules.md","lastUpdated":1794882424000}'),i={name:"kb/rules.md"};function s(d,e,c,n,r,p){return l(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="内容更新规则" tabindex="-1">内容更新规则 <a class="header-anchor" href="#内容更新规则" aria-label="Permalink to &quot;内容更新规则&quot;">​</a></h1><p>这份规则是给「以后每一次更新」用的：写新章、补旧章、改站点，都按这里来。</p><h2 id="三条硬规则" tabindex="-1">三条硬规则 <a class="header-anchor" href="#三条硬规则" aria-label="Permalink to &quot;三条硬规则&quot;">​</a></h2><ol><li><strong>知识要扩充，不是抄录。</strong> 每章除了主线知识，还要补相关延伸内容：能并入正文的并入正文，量太大就单开一页（放 <code>/kb/</code>），并在章节页给出入口。补充内容用自己的话重写，保留可执行的细节，删掉口号。</li><li><strong>所有问题都必须带答案。</strong> 自测题、学生常问、面试题，写完问题紧接着写答案，不允许只留问题。答案要能直接判断对错、能落到代码或命令上。</li><li><strong>术语统一。</strong> <code>章节</code> 一律叫 <strong>测试全栈知识库</strong>，<code>实验</code> 一律叫 <strong>实操记录</strong>。正文里说「本章实操」「实操目录」。</li></ol><h2 id="每一章的结构" tabindex="-1">每一章的结构 <a class="header-anchor" href="#每一章的结构" aria-label="Permalink to &quot;每一章的结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 1. …              主线知识，每节带可运行代码</span></span>
<span class="line"><span>## N. 本章实操        指向 labs/chXX-*，给运行命令</span></span>
<span class="line"><span>## 附：自测答案       先列问题（保持编号），再逐条给答案</span></span>
<span class="line"><span>## 学生常问           Q/A，3–4 条</span></span>
<span class="line"><span>## 面试题             Q/A，3–4 条</span></span>
<span class="line"><span>## 延伸知识           4 条要点</span></span></code></pre></div><p>顺序固定，<code>## 附：自测答案</code> 这个标记用来判断该章是否已补完，不要改名。</p><h2 id="写作口径" tabindex="-1">写作口径 <a class="header-anchor" href="#写作口径" aria-label="Permalink to &quot;写作口径&quot;">​</a></h2><ul><li>先结论后原因：一句话说清该怎么做，再解释为什么。</li><li>能给数字就给数字：超时几秒、重试几次、截断多少字符、并发几个。</li><li>反面例子要写：错误写法 + 为什么错 + 正确写法，三段以内。</li><li>不写来源：不出现课程名、机构名、课件、老师、文档出处。</li><li>不写空话：「非常重要」「一定要重视」删掉，改成具体后果。</li></ul><h2 id="更新流程" tabindex="-1">更新流程 <a class="header-anchor" href="#更新流程" aria-label="Permalink to &quot;更新流程&quot;">​</a></h2><ol><li>改 <code>notes/chXX-*.md</code>（笔记是唯一内容源，站点用 <code>&lt;!--@include--&gt;</code> 引用，不重复维护）。</li><li>需要新页面时：<code>site/kb/&lt;主题&gt;.md</code>，并在 <code>config.mts</code> 侧栏挂上。</li><li>跑测试：<code>.\\.venv\\Scripts\\python.exe -m pytest labs -q</code>，必须全绿。</li><li>本地构建：<code>cd site; npm run build</code>，确认 <code>build complete</code>。</li><li>截图留证：<code>python scripts/shot_site.py</code>、<code>python scripts/shot_live.py</code>。</li><li>提交推送：<code>git add -A; git commit -m &quot;&lt;type&gt;: &lt;一句话&gt;&quot;; git push origin HEAD</code>。</li><li>等 Actions <code>success</code>，再打开线上页面确认内容已更新。</li></ol><h2 id="新增一章的清单" tabindex="-1">新增一章的清单 <a class="header-anchor" href="#新增一章的清单" aria-label="Permalink to &quot;新增一章的清单&quot;">​</a></h2><ul><li>[ ] <code>notes/chXX-&lt;slug&gt;.md</code>：六段结构写全</li><li>[ ] <code>labs/chXX-&lt;slug&gt;/</code>：一个能跑的 demo + 一个 pytest 文件</li><li>[ ] <code>site/chapters/chXX.md</code>：frontmatter + <code>&lt;!--@include--&gt;</code></li><li>[ ] <code>config.mts</code> 侧栏、<code>index.md</code> 进度表、<code>chapters/index.md</code>、<code>labs/index.md</code>、<code>README.md</code> 各加一行</li><li>[ ] 跑 <code>pytest labs -q</code>，文档里的数字与实际一致</li></ul><h2 id="质量红线" tabindex="-1">质量红线 <a class="header-anchor" href="#质量红线" aria-label="Permalink to &quot;质量红线&quot;">​</a></h2><ul><li>文档里的命令必须真跑通，贴的输出必须是真实输出。</li><li>断言必须可判定：写状态码、字段、值或格式，禁止「功能正常」。</li><li>数字（测试条数、章节数、耗时）以实际运行结果为准，改完回头核对首页与索引页。</li></ul>`,15)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
